/****** Object:  View [dbo].[vw_DataSetMetadata]    Script Date: 8/19/2025 4:33:43 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO

CREATE VIEW [dbo].[vw_DataSetMetadata] AS

SELECT

	r.RequestID,

	r.[Name] AS RequestName,

	lap.LoomeAssistProjectsID AS ProjectID,

	lap.LoomeAssistTenantsID AS TenantID,

	lap.AssistProjectID AS AssistProjectID,

	lap.[Name] AS ProjectName,

	lapdr.SourceDataRepoID,

	lapdr.SourceDataRepoName,

	lapdr.SummaryDataRepoID,

	lapdr.SummaryDataRepoName,

	dset.DataSetID,

	dset.[Name] AS DataSetName,

	dst.[Name] AS SourceType,

	dsfv.[Value] AS SourceReference,

	f.[Name] AS ReferenceType

FROM dbo.Request r

INNER JOIN dbo.RequestStatus rs

	ON r.StatusID = rs.StatusID

INNER JOIN dbo.LoomeAssistProjects lap

	ON r.ProjectID = lap.LoomeAssistProjectsID

INNER JOIN dbo.LoomeAssistProjectsDataRepos lapdr

	ON lap.LoomeAssistProjectsID = lapdr.LoomeAssistProjectsID

INNER JOIN dbo.DataSet dset

	ON r.DataSetID = dset.DataSetID

INNER JOIN dbo.DataSource dsrc

	ON dset.DataSourceID = dsrc.DataSourceID

	AND dsrc.IsActive = 1

INNER JOIN dbo.DataSourceType dst

	ON dsrc.DataSourceTypeID = dst.DataSourceTypeID

	AND dst.IsActive = 1

INNER JOIN dbo.DataSourceFieldValue dsfv

	ON dsrc.DataSourceID = dsfv.DataSourceID

INNER JOIN dbo.Field f

	ON dsfv.FieldID = f.FieldID

	AND f.IsActive = 1

LEFT OUTER JOIN (

	SELECT

		RequestID,

		LoggedDate AS LastRefreshDate,

		IsResolved,

		MAX(CASE WHEN IngestionResult = 'Success' THEN LoggedDate END) OVER (PARTITION BY RequestID) AS LastSuccessRefreshDate,

		ROW_NUMBER() OVER (PARTITION BY RequestID ORDER BY LoggedDate DESC) AS RN

	FROM ref.IngestionLog

	WHERE ProjectID IS NULL

	AND DATEDIFF(DAY, LoggedDate, GETDATE()) / 31 <= 1	/* Restrict to match records within 31 days */

) lr

	ON r.RequestID = lr.RequestID

	AND lr.RN = 1

WHERE dset.IsActive = 1

AND (

	/* Pick up requests that are new approved or have never been successfully processed (returned an error but resolved) */

	(

		rs.[Description] = 'Approved'

		AND ISNULL(lr.IsResolved, 1) = 1

	)

	/* Also pick up requests that are finalised but requires scheduled refresh */

	OR (

		rs.[Description] = 'Finalised'

		AND r.ScheduleRefresh <> 'No Refresh'

		/* Identify requests with scheduled refresh that is due */

		AND (CASE r.ScheduleRefresh

					WHEN 'Daily'   THEN DATEDIFF(HOUR, ISNULL(lr.LastSuccessRefreshDate, '1900-01-01'), GETDATE()) / 24

					WHEN 'Weekly'  THEN DATEDIFF(HOUR, ISNULL(lr.LastSuccessRefreshDate, '1900-01-01'), GETDATE()) / 168

					WHEN 'Monthly' THEN DATEDIFF(HOUR, ISNULL(lr.LastSuccessRefreshDate, '1900-01-01'), GETDATE()) / 720

			END) >= 1

		/* Identify requests that have not been processed since last success refresh or are processed recently but failed (returned an error but resolved) */

		AND (

			lr.LastRefreshDate >= lr.LastSuccessRefreshDate

			AND lr.IsResolved = 1

		)

	)

)

GO

