/****** Object:  View [dbo].[vw_REDCapDataSet]    Script Date: 8/19/2025 4:33:43 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO



CREATE VIEW [dbo].[vw_REDCapDataSet] AS

SELECT

	dsm.RequestID,

	dsm.RequestName,

	ds.DataSetID,

	ds.[Name] AS DataSetName,

	ds.[Owner] AS DataSetOwner,

	src.DataSourceName,

	dsm.ProjectID,

	dsm.ProjectName,

	src.APIURL,

	dsfv.[Value] AS APIKey,

	STRING_AGG(dsc.ColumnName, ',') AS ColumnList,

	STRING_AGG(CASE dsc.Tokenise WHEN 1 THEN dsc.ColumnName ELSE '' END, ',') AS TokeniseList,

	STRING_AGG(CASE dsc.Tokenise WHEN 1 THEN COALESCE(em.LM__METADATA__MASTERENTITY, '') ELSE '' END, ',') AS MasterEntityList

FROM dbo.DataSet ds

INNER JOIN (

	SELECT

		ds.DataSourceID,

		ds.[Name] AS DataSourceName,

		dsfv.[Value] AS APIURL

	FROM dbo.DataSource ds

	INNER JOIN dbo.DataSourceFieldValue dsfv

		ON ds.DataSourceID = dsfv.DataSourceID

	INNER JOIN dbo.DataSourceType dst

		ON ds.DataSourceTypeID = dst.DataSourceTypeID

		AND dst.IsActive = 1

		AND dst.[Name] = 'REDCap API'

	INNER JOIN dbo.Field f

		ON dsfv.FieldID = f.FieldID

		AND f.IsActive = 1

		AND f.[Name] = 'REDCap API URL'

	WHERE ds.IsActive = 1

) src

	ON ds.DataSourceID = src.DataSourceID

INNER JOIN dbo.DataSetFieldValue dsfv

	ON ds.DataSetID = dsfv.DataSetID

INNER JOIN dbo.Field f

	ON dsfv.FieldID = f.FieldID

	AND f.IsActive = 1

	AND f.[Name] = 'REDCap API Key'

INNER JOIN dbo.DataSetColumn dsc

	ON ds.DataSetID = dsc.DataSetID

	AND dsc.Redact = 0

INNER JOIN dbo.vw_DataSetMetadata dsm

	ON ds.DataSetID = dsm.DataSetID

LEFT OUTER JOIN ref.EntityMapping em

	ON dsc.DataSetID = em.DataSetID

	AND dsc.DataSetColumnID = em.EntityID

WHERE ds.IsActive = 1

GROUP BY

	dsm.RequestID,

	dsm.RequestName,

	ds.DataSetID,

	ds.[Name],

	ds.[Owner],

	src.DataSourceName,

	dsm.ProjectID,

	dsm.ProjectName,

	src.APIURL,

	dsfv.[Value]

GO

