/****** Object:  View [stg].[vw_OptOutAlertStaging]    Script Date: 8/19/2025 4:33:43 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO

CREATE VIEW [stg].[vw_OptOutAlertStaging]

AS

SELECT

	dso.DataSetID,

	ds.[Name] AS DataSetName,

	dsc.ColumnName,

	em.LM__METADATA__MASTERENTITY AS MasterEntity,

	dsc.Tokenise,

	STRING_AGG(dso.DataSetOptOutID, ',') AS DataSetOptOutIDs,

	STRING_AGG(dso.OptOutValue, ',') AS OptOutValues 

FROM dbo.DataSetOptOut dso

INNER JOIN dbo.DataSet ds

	ON dso.DataSetID = ds.DataSetID

INNER JOIN dbo.DataSetColumn dsc

	ON dso.OptOutColumnID = dsc.DataSetColumnID

LEFT OUTER JOIN ref.EntityMapping em

	ON dsc.DataSetColumnID = em.EntityID

WHERE dso.IsNotified = 0

GROUP BY

	dso.DataSetID,

	ds.[Name],

	dsc.ColumnName,

	em.LM__METADATA__MASTERENTITY,

	dsc.Tokenise

GO

