/****** Object:  View [dbo].[vw_TokeniseEntity]    Script Date: 8/19/2025 4:33:43 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO



CREATE VIEW [dbo].[vw_TokeniseEntity] AS

SELECT

	dsc.DataSetColumnID AS EntityID,

	dsc.DataSetID AS DataSetID,

	dsc.ColumnName AS EntityName,

	ds.[Owner] AS DataSetOwner

FROM dbo.DataSetColumn dsc

INNER JOIN dbo.DataSet ds

	ON dsc.DataSetID = ds.DataSetID

WHERE Redact = 0

AND dsc.Tokenise = 1



UNION ALL



SELECT DISTINCT

	mdt.TokenID,

	ds.DataSetID,

	dsff.EntityName,

	ds.[Owner]

FROM dbo.DataSet ds 

INNER JOIN dbo.DataSource dsrc ON ds.DataSourceID = dsrc.DataSourceID 

INNER JOIN dbo.DataSourceType dst ON dsrc.DataSourceTypeID = dst.DataSourceTypeID 

INNER JOIN dbo.DataSetFolder dsf ON ds.DataSetID = dsf.DataSetID

INNER JOIN (

	SELECT DISTINCT

		DataSetFolderID,

		value AS EntityName

	FROM dbo.DataSetFolderFile 

	CROSS APPLY string_split(TokeniseRule, '-')

) dsff ON dsf.DataSetFolderID = dsff.DataSetFolderID

INNER JOIN dbo.MetaDataTokens mdt

	ON mdt.Token = dsff.EntityName

WHERE dst.[Name] = 'Folder'

AND mdt.Deidentify = 1

GO

