CREATE VIEW [dbo].[vw_DatabaseDataSet]

AS

SELECT dsm.RequestID, dsm.RequestName, ds.DataSetID, ds.Name AS DataSetName, ds.Owner AS DataSetOwner, dbconn.DataSourceName, dsm.ProjectID, dsm.ProjectName, dbconn.IntegrateConnectionID, ldst.TableName, STRING_AGG(dsc.ColumnName, ',') AS ColumnList, 

             STRING_AGG(CASE dsc.Tokenise WHEN 1 THEN dsc.ColumnName ELSE '' END, ',') AS TokeniseList, STRING_AGG(CASE dsc.Tokenise WHEN 1 THEN COALESCE (em.LM__METADATA__MASTERENTITY, '') ELSE '' END, ',') AS MasterEntityList, 

             STRING_AGG(CASE FilterType WHEN 'BETWEEN' THEN rfv.ColumnName + ' ' + rfv.FilterType + ' ' + rfv.Value1 + ' AND ' + rfv.Value2 WHEN 'IN' THEN rfv.ColumnName + ' ' + rfv.FilterType + ' (' + REPLACE(rfv.Value1, ',', ''',''') 

             + ')' ELSE rfv.ColumnName + ' ' + rfv.FilterType + ' ' + rfv.Value1 END, ' AND ') AS FilterClause

FROM   dbo.DataSet AS ds INNER JOIN

                 (SELECT ds.DataSourceID, ds.Name AS DataSourceName, dsfv.Value AS IntegrateConnectionID

                 FROM    dbo.DataSource AS ds INNER JOIN

                              dbo.DataSourceFieldValue AS dsfv ON ds.DataSourceID = dsfv.DataSourceID INNER JOIN

                              dbo.DataSourceType AS dst ON ds.DataSourceTypeID = dst.DataSourceTypeID AND dst.IsActive = 1 AND dst.Name = 'Database' INNER JOIN

                              dbo.Field AS f ON dsfv.FieldID = f.FieldID AND f.IsActive = 1 AND f.Name = 'Database Connection'

                 WHERE (ds.IsActive = 1)) AS dbconn ON ds.DataSourceID = dbconn.DataSourceID INNER JOIN

             dbo.DataSetFieldValue AS dsfv ON ds.DataSetID = dsfv.DataSetID INNER JOIN

             dbo.Field AS f ON dsfv.FieldID = f.FieldID AND f.IsActive = 1 AND f.Name = 'Table Name' INNER JOIN

             dbo.LoomeDataSourceTables AS ldst ON dsfv.Value = CAST(ldst.Id AS varchar(10)) AND ldst.isActive = 1 INNER JOIN

             dbo.DataSetColumn AS dsc ON ds.DataSetID = dsc.DataSetID AND dsc.Redact = 0 INNER JOIN

             dbo.vw_DataSetMetadata AS dsm ON ds.DataSetID = dsm.DataSetID LEFT OUTER JOIN

             ref.EntityMapping AS em ON dsc.DataSetID = em.DataSetID AND dsc.DataSetColumnID = em.EntityID LEFT OUTER JOIN

                 (SELECT RequestID, ColumnName, UPPER(FilterType) AS FilterType, CASE WHEN ColumnType IN ('bit', 'decimal', 'numeric', 'float', 'real', 'int', 'bigint', 'smallint', 'tinyint', 'money', 'smallmoney') THEN Value1 ELSE '''' + REPLACE(Value1, '''', '''''') + '''' END AS Value1, 

                              CASE WHEN ColumnType IN ('bit', 'decimal', 'numeric', 'float', 'real', 'int', 'bigint', 'smallint', 'tinyint', 'money', 'smallmoney') THEN Value2 ELSE '''' + REPLACE(Value2, '''', '''''') + '''' END AS Value2

                 FROM    dbo.RequestFilterValue

                 WHERE (FilterType <> 'None')) AS rfv ON dsm.RequestID = rfv.RequestID AND dsc.ColumnName = rfv.ColumnName

WHERE (ds.IsActive = 1)

GROUP BY dsm.RequestID, dsm.RequestName, ds.DataSetID, ds.Name, ds.Owner, dbconn.DataSourceName, dsm.ProjectID, dsm.ProjectName, dbconn.IntegrateConnectionID, ldst.TableName

GO

/****** Object:  View [dbo].[vw_DataSourceMetadata]    Script Date: 8/19/2025 4:33:43 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO

CREATE VIEW [dbo].[vw_DataSourceMetadata] AS

SELECT

	ds.DataSourceID,

	ds.[Name] AS DataSourceName,

	dst.[Name] AS SourceType,

	dsfv.[Value] AS SourceReference,

	f.[Name] AS ReferenceType

FROM dbo.DataSource ds

INNER JOIN dbo.DataSourceType dst

	ON ds.DataSourceTypeID = dst.DataSourceTypeID

	AND dst.IsActive = 1

INNER JOIN dbo.DataSourceFieldValue dsfv

	ON ds.DataSourceID = dsfv.DataSourceID

INNER JOIN dbo.Field f

	ON dsfv.FieldID = f.FieldID

	AND dst.IsActive = 1

WHERE ds.IsActive = 1

AND ds.isRefreshed = 0

AND dst.[Name] IN ('Database', 'Folder')

GO

/****** Object:  View [stg].[vw_DataSetOptOutStaging]    Script Date: 8/19/2025 4:33:43 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO

CREATE VIEW [stg].[vw_DataSetOptOutStaging] AS

SELECT

	ds.DataSetID,

	CONVERT(datetime, LEFT(list.[value], FirstDelimLoc), 103) AS CreateDate,

	SUBSTRING(list.[value], FirstDelimLoc + 3, SecondDelimLoc - FirstDelimLoc - 3) AS CreateUser,

	TRIM(SUBSTRING(list.[value], SecondDelimLoc + 3, LEN(list.[value]))) AS OptOutValue,

	ds.OptOutColumn AS OptOutColumnID,

	CASE WHEN r.DataSetID IS NULL THEN 1 ELSE 0 END AS IsNotified

FROM dbo.DataSet ds

	CROSS APPLY string_split(OptOutList, CHAR(10)) list

INNER JOIN (

	SELECT

		DataSetID,

		[value],

		CHARINDEX(' - ', [value]) AS FirstDelimLoc,

		CHARINDEX(' - ', [value], CHARINDEX(' - ', [value]) + 3) AS SecondDelimLoc

	FROM dbo.DataSet

		CROSS APPLY string_split(OptOutList, CHAR(10))

	WHERE [value] <> ''

) ref

	ON ds.DataSetID = ref.DataSetID

	AND list.[value] = ref.[value]

LEFT OUTER JOIN (

	SELECT DISTINCT

		DataSetID

	FROM dbo.Request r

	INNER JOIN dbo.RequestStatus rs

		ON r.StatusID = rs.StatusID

		AND rs.[Description] = 'Finalised'

) r

	ON ds.DataSetID = r.DataSetID

WHERE list.[value] <> ''

AND NOT EXISTS (

	select 1

	FROM dbo.DataSetOptOut dso

	WHERE ds.DataSetID = dso.DataSetID

	AND list.[value] = (FORMAT(dso.CreateDate, 'dd/MM/yyyy hh:mm:ss') + ' - ' + dso.CreateUser + ' - ' + dso.OptOutValue)

)

GO

/****** Object:  View [dbo].[vw_FileDataSet]    Script Date: 8/19/2025 4:33:43 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO



CREATE VIEW [dbo].[vw_FileDataSet] AS

SELECT

	dsm.RequestID,

	dsm.RequestName,

	ds.DataSetID,

	ds.[Name] AS DataSetName,

	ds.[Description] AS DataSetDescription,

	ds.[Owner] AS DataSetOwner,

	src.DataSourceName,

	dsm.ProjectID,

	dsm.ProjectName,

	src.FilePath AS RootPath,

	dsf.FolderName,

	dsf.[Description] AS FolderDescription,

	COALESCE(dsff.FileType, '') AS FileType,

	dsff.FileDescription,

	COALESCE(dsff.TokeniseRule, '') AS TokeniseRule

FROM dbo.DataSet ds

INNER JOIN (

	SELECT

		ds.DataSourceID,

		ds.[Name] AS DataSourceName,

		dsfv.[Value] AS FilePath

	FROM dbo.DataSource ds

	INNER JOIN dbo.DataSourceFieldValue dsfv

		ON ds.DataSourceID = dsfv.DataSourceID

	INNER JOIN dbo.DataSourceType dst

		ON ds.DataSourceTypeID = dst.DataSourceTypeID

		AND dst.IsActive = 1

		AND dst.[Name] = 'Folder'

	INNER JOIN dbo.Field f

		ON dsfv.FieldID = f.FieldID

		AND f.IsActive = 1

		AND f.[Name] = 'UNC Path'

	WHERE ds.IsActive = 1

) src

	ON ds.DataSourceID = src.DataSourceID

INNER JOIN dbo.DataSetFieldValue dsfv

	ON ds.DataSetID = dsfv.DataSetID

INNER JOIN dbo.Field f

	ON dsfv.FieldID = f.FieldID

	AND f.IsActive = 1

	AND f.[Name] = 'Folder Name'

INNER JOIN dbo.DataSetFolder dsf

	ON ds.DataSetID = dsf.DataSetID

LEFT OUTER JOIN dbo.DataSetFolderFile dsff

	ON dsf.DataSetFolderID = dsff.DataSetFolderID

INNER JOIN dbo.vw_DataSetMetadata dsm

	ON ds.DataSetID = dsm.DataSetID

WHERE ds.IsActive = 1

GO

