INSERT [dbo].[DataSetColumn] ([DataSetColumnID], [DataSetID], [ColumnName], [ColumnType], [LogicalColumnName], [BusinessDescription], [ExampleValue], [Tokenise], [TokenIdentifierType], [Redact], [DisplayOrder], [IsFilter]) VALUES (950, 10, N'scid_a_manspec_mixa6', N'dropdown', N'scid5rv_a_mood_disorders_specifiers_for_current_ma - scid_a_manspec_mixa6', N'6.	Recurrent thoughts of death (not just fear of dying), recurrent suicidal ideation without a specific plan, or a suicide attempt or a specific plan for committing suicide.

