INSERT [dbo].[DataSetColumn] ([DataSetColumnID], [DataSetID], [ColumnName], [ColumnType], [LogicalColumnName], [BusinessDescription], [ExampleValue], [Tokenise], [TokenIdentifierType], [Redact], [DisplayOrder], [IsFilter]) VALUES (1039, 10, N'scid_a_k_specify', N'dropdown', N'scid5rv_a_mood_disorders_k_gmc_bipolar_and_related - scid_a_k_specify', N'Specify if', N'1, 1 - With manic features: Full criteria are not met for a manic or hypomanic episode. | 2, 2 - With manic- or hypomanic-like episode: Full criteria are met except Criterion D for a manic episode or except Criterion F for a hypomanic episode. | 3, 3 - With mixed features: Symptoms of depression are also present but do not predominate in the clinical picture.', 0, 0, 1, 323, 0)

