INSERT [dbo].[DataSetColumn] ([DataSetColumnID], [DataSetID], [ColumnName], [ColumnType], [LogicalColumnName], [BusinessDescription], [ExampleValue], [Tokenise], [TokenIdentifierType], [Redact], [DisplayOrder], [IsFilter]) VALUES (1073, 10, N'scid_a_m_specify', N'dropdown', N'scid5rv_a_mood_disorders_m_gmc_depressive_disorder - scid_a_m_specify', N'Specify if:', N'1, 1 - With depressive features: Full criteria are not met for a major depressive episode. | 2, 2 - With major depressive-like episode: Full criteria are met (except Criterion C) for a major depressive episode. | 3, 3 - With mixed features: Symptoms of mania or hypomania are also present but do not predominate in the clinical picture.', 0, 0, 1, 340, 0)

