INSERT [dbo].[DataSetColumn] ([DataSetColumnID], [DataSetID], [ColumnName], [ColumnType], [LogicalColumnName], [BusinessDescription], [ExampleValue], [Tokenise], [TokenIdentifierType], [Redact], [DisplayOrder], [IsFilter]) VALUES (1082, 10, N'scid_a_sum', N'calc', N'scid5rv_a_mood_disorders_a_current_mde - scid_a_sum', N'Module A summary. 

