INSERT [dbo].[DataSetColumn] ([DataSetColumnID], [DataSetID], [ColumnName], [ColumnType], [LogicalColumnName], [BusinessDescription], [ExampleValue], [Tokenise], [TokenIdentifierType], [Redact], [DisplayOrder], [IsFilter]) VALUES (1122, 10, N'scid_a_mixeda1', N'dropdown', N'scid5rv_a_mood_disorders_a_current_mde - scid_a_mixeda1', N'A. At least three of the following manic/ hypomanic symptoms are present [...] during the majority of days of the current episode of depression:



