INSERT [dbo].[DataSetColumn] ([DataSetColumnID], [DataSetID], [ColumnName], [ColumnType], [LogicalColumnName], [BusinessDescription], [ExampleValue], [Tokenise], [TokenIdentifierType], [Redact], [DisplayOrder], [IsFilter]) VALUES (1242, 10, N'scid_a_atypb1', N'dropdown', N'scid5rv_a_mood_disorders_a_current_mde - scid_a_atypb1', N'B. Two (or more) of the following features:



