INSERT [dbo].[DataSetColumn] ([DataSetColumnID], [DataSetID], [ColumnName], [ColumnType], [LogicalColumnName], [BusinessDescription], [ExampleValue], [Tokenise], [TokenIdentifierType], [Redact], [DisplayOrder], [IsFilter]) VALUES (1527, 10, N'scid_f_aa', N'dropdown', N'scid5rv_f_anxiety_disorders - scid_f_aa', N'A panic attack is an abrupt surge of intense fear or intense discomfort that reaches a peak within minutes.



Note: The abrupt surge can occur from a calm state or an anxious state.



~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

...IF UNKNOWN: Did the symptoms come on suddenly?



...IF YES: How long did it take from when it began to when it got really bad? (Did it happen within a few minutes?)', N'-99, -99 inadequate information | 1, 1 absent or false | 2, 2 subthreshold | 3, 3 threshold or true', 0, 0, 1, 506, 0)

