/****** Object:  StoredProcedure [dbo].[sprSyncDataSetToPublish]    Script Date: 8/19/2025 4:33:44 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO

--"id": 48 -- general

--  "id": 1, redcap

-- "id": 2, database

--  "id": 3, folder



CREATE proc [dbo].[sprSyncDataSetToPublish] as



SET IDENTITY_INSERT [Publish].[Assets] ON







truncate table [Publish].[AssetTerms]

truncate table [Publish].[AssetTags]

delete from [Publish].[Assets]

INSERT INTO [Publish].[Assets]

           (ID,

		   [Name]

           ,[Type]

           ,[Description]

           ,[SubType]

           ,[Url])

select

Datasetid 

,[Name]

,'Data Lake' [Type]

,[Description]

,'Web' [SubType]

,'https://workflow.sheba.org.au/request/' + convert(varchar(50),DataSetID) [Url]

from dataset



SET IDENTITY_INSERT [Publish].[Assets] OFF









INSERT INTO [Publish].[AssetTags]

           ([AssetId]

           ,[Tag])

select 

(



select ID from publish.assets a

inner join dataset ds on ds.name = a.name and ds.description = a.description

where ds.datasetid = d.datasetid

) as [AssetId]



,m.name + ':' + v.value [Tag]



--,v.*,m.*

           --,[Tag]

from DataSetMetaDataValue v

inner join dataset d on d.DataSetID = v.DataSetID

inner join metadata m on m.metadataid = v.metadataid

where v.value is not null







/* Temporarily disable the function to assign default asset terms (business area & subject area) - Luke Chen 2022-05-09

INSERT INTO [Publish].[AssetTerms]

           ([AssetId]

           ,[TermId])





select 

(

select ID from publish.assets a

inner join dataset ds on ds.name = a.name and ds.description = a.description

where ds.datasetid = d.datasetid

) as [AssetId]

--,(

--Select case 

--when t.name = 'REDCap API' then 1

--when t.name = 'Database' then 2

--when t.name = 'Folder' then 3

--end

--from datasourcetype t

--inner join datasource ds on ds.[DataSourceTypeID] = t.[DataSourceTypeID]

--where ds.DataSourceid = d.DataSourceid ) as TermId

,1 TermId

from dataset d 



union all



select 

(

select ID from publish.assets a

inner join dataset ds on ds.name = a.name and ds.description = a.description

where ds.datasetid = d.datasetid

) as [AssetId]

,48 TermId

from dataset d 

*/

GO

/****** Object:  StoredProcedure [dbo].[sprUpdatePendingApprovalEmail]    Script Date: 8/19/2025 4:33:44 AM ******/

SET ANSI_NULLS ON

GO

SET QUOTED_IDENTIFIER ON

GO



CREATE proc [dbo].[sprUpdatePendingApprovalEmail] as



--delete from [RequestEmailTracking]

--where requestid in (

--	select requestid from request

--	where statusid <> (select statusid from [dbo].[RequestStatus] where description = 'Pending Approval')

--)



-- pending approval

-- truncate table [RequestEmailTracking]

INSERT INTO [dbo].[RequestEmailTracking]

           ([RequestID]

           ,[EmailType]

           ,[DateSent])

select 

	[RequestID]

	,'RequestApproval' as [EmailType]

	,null as [DateSent]

	

from request

where statusid = (select statusid from [dbo].[RequestStatus] where description = 'Pending Approval')

and requestid not in (

	select requestid

	from RequestEmailTracking

	where [EmailType] = 'RequestApproval'

)





--and requestid = 44



-- rejected

update [dbo].[RequestEmailTracking]

set [EmailType] = 'RequestRejected',[DateSent] = null

from [RequestEmailTracking]

where [EmailType] = 'RequestApproval'

and requestid in (

	select requestid

	from Request

	where statusid = (select statusid from [dbo].[RequestStatus] where description = 'Rejected')

)



-- approved

update [dbo].[RequestEmailTracking]

set [EmailType] = 'RequestApproved',[DateSent] = null

from [RequestEmailTracking]

where [EmailType] = 'RequestApproval'

and requestid in (

	select requestid 

	from Request

	where statusid = (select statusid from [dbo].[RequestStatus] where description = 'Approved')

)





declare @requestid int, @datasetdetails varchar(max)



delete from RequestEmails



-- request approval

DECLARE db_cursor CURSOR FOR 

select 

	et.requestid

from [dbo].[RequestEmailTracking] et

inner join request r on r.requestid = et.requestid

where [EmailType] = 'RequestApproval'

and dateSent is null 

--or datediff(d,getdate(),datesent) <= -7

OPEN db_cursor  

FETCH NEXT FROM db_cursor INTO @requestid



SELECT * FROM RequestEmails



WHILE @@FETCH_STATUS = 0  

BEGIN  

	  select @datasetdetails = '<p><ul><li><b>Request Name:</b> ' + r.[Name] + '</li><li><b>Researcher:</b> ' + r.CreateUser + '</li><li><b>Data Set Name:</b> ' + replace(d.[Name],'''', '''''') + '</li><li><b>Data Set Description:</b> ' + replace(d.[Description],'''', '''''') + '</li><li><b>Purpose:</b> ' + 'Purpose' + '</li></ul></p>'

	  from request r

	  inner join dataset d on d.datasetid = r.datasetid

	  where requestid = @requestid

	  

	  insert into RequestEmails

	  SELECT 

	  

	  ltrim(rtrim(value)) as EmailTo

	  ,(select [EmailTemplateSubject] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestApproval') as EmailSubject

	  ,(select [EmailTemplateText] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestApproval') + @datasetdetails as EmailBody

	  ,'RequestApproval' AS EmailType

	  FROM STRING_SPLIT((select approvers from request where requestid = @requestid),';')



	  update [RequestEmailTracking] set datesent = getdate() where requestid = @requestid

      FETCH NEXT FROM db_cursor INTO @requestid 

END 



CLOSE db_cursor  

DEALLOCATE db_cursor 



-- approved



DECLARE db_cursor CURSOR FOR 

select 

	et.requestid

from [dbo].[RequestEmailTracking] et

inner join request r on r.requestid = et.requestid

where [EmailType] = 'RequestApproved'

and dateSent is null 

OPEN db_cursor  

FETCH NEXT FROM db_cursor INTO @requestid



WHILE @@FETCH_STATUS = 0  

BEGIN  

	  select @datasetdetails = '<p><ul><li><b>Request Name:</b> ' + r.[Name] + '</li><li><b>Data Set Name:</b> ' + replace(d.[Name],'''', '''''') + '</li><li><b>Data Set Description:</b> ' + replace(d.[Description],'''', '''''') + '</li><li><b>Approved By:</b> ' + r.[Approvers] + '</li><li><b>Research Workspace Project:</b> ' + p.[Name] + '</li></ul></p>'

	  from request r

	  inner join dataset d on d.datasetid = r.datasetid

	  inner join LoomeAssistProjects p on p.LoomeAssistProjectsID = r.ProjectID

	  where requestid = @requestid

	  

	  insert into RequestEmails

	  SELECT 

	 

	  ltrim(rtrim(createuser)) as EmailTo

	  ,(select [EmailTemplateSubject] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestApproved') as EmailSubject

	  ,(select [EmailTemplateText] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestApproved') + @datasetdetails as EmailBody

	  ,'RequestApproved' AS EmailType

	  FROM request where requestid = @requestid



	  update [RequestEmailTracking] set datesent = getdate() where requestid = @requestid

      FETCH NEXT FROM db_cursor INTO @requestid 

END 



CLOSE db_cursor  

DEALLOCATE db_cursor 



-- rejected

DECLARE db_cursor CURSOR FOR 

select 

	et.requestid

from [dbo].[RequestEmailTracking] et

inner join request r on r.requestid = et.requestid

where [EmailType] = 'RequestRejected'

and dateSent is null 

OPEN db_cursor  

FETCH NEXT FROM db_cursor INTO @requestid



WHILE @@FETCH_STATUS = 0  

BEGIN  

	  select @datasetdetails = '<p><ul><li><b>Request Name:</b> ' + r.[Name] + '</li><li><b>Data Set Name:</b> ' + replace(d.[Name],'''', '''''') + '</li><li><b>Data Set Description:</b> ' + replace(d.[Description],'''', '''''') + '</li><li><b>Approver(s):</b> ' + r.[Approvers] + '</li><li><b>Research Workspace Project:</b> ' + p.[Name] + '</li><li><b>Reason:</b> ' + replace(r.[RequestMessage],'''', '''''') + '</li></ul></p>'

	  from request r

	  inner join dataset d on d.datasetid = r.datasetid

	  inner join LoomeAssistProjects p on p.LoomeAssistProjectsID = r.ProjectID

	  where requestid = @requestid

	  

	  insert into RequestEmails

	  SELECT 

	 

	  ltrim(rtrim(createuser)) as EmailTo

	  ,(select [EmailTemplateSubject] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestRejected') as EmailSubject

	  ,(select [EmailTemplateText] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestRejected') + @datasetdetails as EmailBody

	  ,'RequestRejected' AS EmailType

	  FROM request where requestid = @requestid



	  update [RequestEmailTracking] set datesent = getdate() where requestid = @requestid

      FETCH NEXT FROM db_cursor INTO @requestid 

END 



CLOSE db_cursor  

DEALLOCATE db_cursor 



-- escalate pending approval

DECLARE db_cursor CURSOR FOR 

select 

	et.requestid

from [dbo].[RequestEmailTracking] et

inner join request r on r.requestid = et.requestid

inner join RequestStatus rs on rs.StatusID = r.StatusID

where [EmailType] = 'RequestApproval'

and rs.Description = 'Pending Approval'

and DATEDIFF(HOUR, dateSent, GETDATE()) > 48

OPEN db_cursor  

FETCH NEXT FROM db_cursor INTO @requestid



WHILE @@FETCH_STATUS = 0  

BEGIN  

	  select @datasetdetails = '<p><ul><li><b>Request Name:</b> ' + r.[Name] + '</li><li><b>Researcher:</b> ' + r.CreateUser + '</li><li><b>Data Set Name:</b> ' + replace(d.[Name],'''', '''''') + '</li><li><b>Data Set Description:</b> ' + replace(d.[Description],'''', '''''') + '</li><li><b>Approver:</b> ' + replace(r.Approvers,'''', '''''') + '</li><li><b>CurrentlyApproved:</b> ' + COALESCE(replace(r.CurrentlyApproved,'''', ''''''), '') + '</li><li><b>Purpose:</b> ' + 'Purpose' + '</li></ul></p>'

	  from request r

	  inner join dataset d on d.datasetid = r.datasetid

	  where requestid = @requestid

	  

	  insert into RequestEmails

	  SELECT 

	  

	  'sheba-datamanager@deakin.edu.au' as EmailTo

	  ,(select [EmailTemplateSubject] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestEscalated') as EmailSubject

	  ,(select [EmailTemplateText] from [dbo].[EmailTemplate] where [EmailTemplateType] = 'RequestEscalated') + @datasetdetails as EmailBody

	  ,'RequestEscalated' AS EmailType

	  --FROM STRING_SPLIT((select approvers from request where requestid = @requestid),';')



	  update [RequestEmailTracking] set datesent = getdate() where requestid = @requestid

      FETCH NEXT FROM db_cursor INTO @requestid 

END 



CLOSE db_cursor  

DEALLOCATE db_cursor





--select * from [RequestEmailTracking]

--select * from RequestEmails







GO

